    await templateFolder.append("/dry-mixed/wire.json")
      .write('[{"where":"top","content":"// header\\n"}]');

    const output = await captureStdout(() => apply.run({
      subcommands: ["dry-mixed"],
      flags: [
        { flag: "--dry-run", value: "true" },
        { flag: "--component-name", value: "Widget" },
